// Closest Java equivalent: a javac annotation processor
@SupportedAnnotationTypes("workbench.ksp.annotations.Inventory")
@SupportedSourceVersion(SourceVersion.RELEASE_21)
public class InventoryProcessor extends AbstractProcessor {
    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        Elements elements = processingEnv.getElementUtils();
        TypeElement inventory = elements.getTypeElement("workbench.ksp.annotations.Inventory");
        for (Element element : roundEnv.getElementsAnnotatedWith(inventory)) {      // 1. Find
            if (element.getKind() != ElementKind.CLASS) {                           // 2. Check
                processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR,
                        "@Inventory goes on a class", element);
                continue;
            }
            TypeElement cls = (TypeElement) element;
            String pkg = elements.getPackageOf(cls).getQualifiedName().toString();
            String name = cls.getSimpleName().toString();
            try (Writer out = processingEnv.getFiler()                              // 4. Write
                    .createSourceFile(pkg + "." + name + "InventoryCard", cls).openWriter()) {
                out.write("package " + pkg + ";\n...");
            } catch (IOException e) {
                processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR, e.toString(), cls);
            }
        }
        return false;
    }
}
// registered in META-INF/services/javax.annotation.processing.Processor

kotlin.src:
class InventoryProcessorProvider : SymbolProcessorProvider {
    override fun create(environment: SymbolProcessorEnvironment): SymbolProcessor =
        InventoryProcessor(environment.codeGenerator, environment.logger)
}

class InventoryProcessor(
    private val codeGenerator: CodeGenerator,
    private val logger: KSPLogger,
) : SymbolProcessor {
    override val apiFeatures = buildApiFeatures { enableBackingFields = true; enableContextParameters = true }

    override fun process(resolver: Resolver): List<KSAnnotated> {
        for (symbol in resolver.getSymbolsWithAnnotation("workbench.ksp.annotations.Inventory")) {   // 1. Find
            if (symbol !is KSClassDeclaration || symbol.classKind != ClassKind.CLASS) {          // 2. Check
                logger.error("@Inventory goes on a class", symbol)
                continue
            }
            val names = symbol.primaryConstructor?.parameters.orEmpty()                           // 3. Read
                .filter { it.isVal || it.isVar }.map { it.name!!.asString() }
            codeGenerator.createNewFile(                                                          // 4. Write
                Dependencies(false, symbol.containingFile!!),
                symbol.packageName.asString(), "${symbol.simpleName.asString()}InventoryCard",
            ).use { it.write(cardSource(symbol, names).toByteArray()) }
        }
        return emptyList()
    }
}
// registered in META-INF/services/com.google.devtools.ksp.processing.SymbolProcessorProvider

