class HelloProvider : SymbolProcessorProvider {
    override fun create(environment: SymbolProcessorEnvironment): SymbolProcessor =
        HelloProcessor(environment.codeGenerator)
}

class HelloProcessor(private val codeGenerator: CodeGenerator) : SymbolProcessor {
    override val apiFeatures = buildApiFeatures { enableBackingFields = true; enableContextParameters = true }

    override fun process(resolver: Resolver): List<KSAnnotated> {
        for (cls in resolver.getSymbolsWithAnnotation("workbench.ksp.annotations.smoke.Hello")
            .filterIsInstance<KSClassDeclaration>()) {
            val name = cls.simpleName.asString()
            val pkg = cls.packageName.asString()
            codeGenerator.createNewFile(Dependencies(false, cls.containingFile!!), pkg, "${name}Hello")
                .use { it.write("package $pkg\n\nfun helloFrom$name() = \"Hello from $name\"\n".toByteArray()) }
        }
        return emptyList()
    }
}

