@SupportedAnnotationTypes("workbench.ksp.annotations.smoke.Hello")
@SupportedSourceVersion(SourceVersion.RELEASE_21)
public class HelloProcessor extends AbstractProcessor {
    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        TypeElement hello = processingEnv.getElementUtils().getTypeElement("workbench.ksp.annotations.smoke.Hello");
        for (Element element : roundEnv.getElementsAnnotatedWith(hello)) {
            String name = element.getSimpleName().toString();
            String pkg = processingEnv.getElementUtils().getPackageOf(element).getQualifiedName().toString();
            try (Writer out = processingEnv.getFiler().createSourceFile(pkg + "." + name + "Hello", element).openWriter()) {
                out.write("package " + pkg + ";\n\npublic final class " + name + "Hello {\n"
                        + "    public static String helloFrom" + name + "() { return \"Hello from " + name + "\"; }\n}\n");
            } catch (IOException e) {
                processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR, e.toString(), element);
            }
        }
        return false;
    }
}
